import matter from 'gray-matter';
import { marked } from 'marked';

export interface PageMetadata {
  title?: string;
  date?: string;
  tags?: string[];
  [key: string]: string | string[] | undefined;
}

export interface ParsedPage {
  content: string;
  metadata: PageMetadata;
}

function parseYamlFrontmatter(yamlStr: string): Record<string, string | string[]> {
  const result: Record<string, string | string[]> = {};
  const lines = yamlStr.trim().split('\n');

  for (const line of lines) {
    const colonIndex = line.indexOf(':');
    if (colonIndex === -1) continue;

    const key = line.substring(0, colonIndex).trim();
    const value = line.substring(colonIndex + 1).trim();

    if (key === 'tags') {
      result[key] = value.split(',').map(tag => tag.trim());
    } else {
      result[key] = value;
    }
  }

  return result;
}

export function parseMarkdown(content: string): ParsedPage {
  const result = matter(content);

  let metadata: PageMetadata = {};

  if (typeof result.data === 'object' && result.data !== null) {
    metadata = result.data as PageMetadata;
  }

  const html = marked.parse(result.content);

  return {
    content: html,
    metadata
  };
}

export function parseMarkdownWithYaml(content: string): ParsedPage {
  const fencedRegex = /^---\n([\s\S]*?)\n---\n/;
  const match = content.match(fencedRegex);

  let metadata: PageMetadata = {};
  let markdown = content;

  if (match) {
    const yamlBlock = match[1];
    markdown = content.substring(match[0].length);

    const parsedYaml = parseYamlFrontmatter(yamlBlock);
    metadata = {
      title: parsedYaml.title as string | undefined,
      date: parsedYaml.date as string | undefined,
      tags: Array.isArray(parsedYaml.tags) ? parsedYaml.tags : undefined,
      ...Object.fromEntries(
        Object.entries(parsedYaml).filter(([key]) => !['title', 'date', 'tags'].includes(key))
      )
    };
  }

  const html = marked.parse(markdown);

  return {
    content: html,
    metadata
  };
}

import fs from 'fs';
import path from 'path';
import { parseMarkdownWithYaml, type PageMetadata } from './parser.js';

export interface PageData {
  slug: string;
  filename: string;
  content: string;
  metadata: PageMetadata;
}

export interface GeneratorOptions {
  contentDir: string;
  outputDir: string;
}

function slugFromFilename(filename: string): string {
  return filename.replace(/\.md$/, '');
}

function generatePageHtml(page: PageData): string {
  const title = page.metadata.title || page.slug;
  const date = page.metadata.date ? `<p class="date">${page.metadata.date}</p>` : '';
  const tags = page.metadata.tags && page.metadata.tags.length > 0
    ? `<div class="tags">${page.metadata.tags.map(tag => `<span class="tag">${tag}</span>`).join('')}</div>`
    : '';

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${escapeHtml(title)}</title>
  <style>
    body { font-family: sans-serif; line-height: 1.6; max-width: 800px; margin: 0 auto; padding: 20px; }
    a { color: #0066cc; }
    .date { color: #666; font-size: 0.9em; }
    .tags { margin: 10px 0; }
    .tag { display: inline-block; background: #f0f0f0; padding: 2px 8px; margin: 2px; border-radius: 3px; font-size: 0.9em; }
    nav { border-bottom: 1px solid #ddd; margin-bottom: 20px; padding-bottom: 10px; }
  </style>
</head>
<body>
  <nav>
    <a href="index.html">← Home</a>
  </nav>
  <article>
    <h1>${escapeHtml(title)}</h1>
    ${date}
    ${tags}
    <div class="content">
      ${page.content}
    </div>
  </article>
</body>
</html>`;
}

function generateIndexHtml(pages: PageData[]): string {
  const pageLinks = pages
    .sort((a, b) => {
      const dateA = new Date(a.metadata.date || '').getTime();
      const dateB = new Date(b.metadata.date || '').getTime();
      return dateB - dateA;
    })
    .map(page => {
      const title = page.metadata.title || page.slug;
      const dateStr = page.metadata.date ? ` (${page.metadata.date})` : '';
      return `<li><a href="${page.slug}.html">${escapeHtml(title)}</a>${dateStr}</li>`;
    })
    .join('\n    ');

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Home</title>
  <style>
    body { font-family: sans-serif; line-height: 1.6; max-width: 800px; margin: 0 auto; padding: 20px; }
    a { color: #0066cc; }
    li { margin: 8px 0; }
  </style>
</head>
<body>
  <h1>Pages</h1>
  <ul>
    ${pageLinks}
  </ul>
</body>
</html>`;
}

function escapeHtml(text: string): string {
  const map: Record<string, string> = {
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#039;'
  };
  return text.replace(/[&<>"']/g, char => map[char]);
}

export async function generate(options: GeneratorOptions): Promise<void> {
  const { contentDir, outputDir } = options;

  if (!fs.existsSync(contentDir)) {
    throw new Error(`Content directory not found: ${contentDir}`);
  }

  if (!fs.existsSync(outputDir)) {
    fs.mkdirSync(outputDir, { recursive: true });
  }

  const files = fs.readdirSync(contentDir).filter(file => file.endsWith('.md'));

  if (files.length === 0) {
    throw new Error(`No markdown files found in ${contentDir}`);
  }

  const pages: PageData[] = [];

  for (const file of files) {
    const filePath = path.join(contentDir, file);
    const content = fs.readFileSync(filePath, 'utf-8');
    const parsed = parseMarkdownWithYaml(content);

    const page: PageData = {
      slug: slugFromFilename(file),
      filename: file,
      content: parsed.content,
      metadata: parsed.metadata
    };

    pages.push(page);

    const pageHtml = generatePageHtml(page);
    const outputPath = path.join(outputDir, `${page.slug}.html`);
    fs.writeFileSync(outputPath, pageHtml, 'utf-8');
  }

  const indexHtml = generateIndexHtml(pages);
  const indexPath = path.join(outputDir, 'index.html');
  fs.writeFileSync(indexPath, indexHtml, 'utf-8');

  console.log(`Generated site with ${pages.length} page(s) in ${outputDir}`);
}

export interface CliArgs {
  command: string;
  contentDir: string;
  outputDir: string;
}

export function parseArgs(argv: string[]): CliArgs {
  const args: CliArgs = {
    command: 'build',
    contentDir: './content',
    outputDir: './dist'
  };

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];

    if (arg === '--content' && i + 1 < argv.length) {
      args.contentDir = argv[++i];
    } else if (arg === '--output' && i + 1 < argv.length) {
      args.outputDir = argv[++i];
    } else if (arg === 'build') {
      args.command = 'build';
    }
  }

  return args;
}

#!/usr/bin/env node

import { parseArgs } from './cli.js';
import { generate } from './generator.js';

const args = parseArgs(process.argv.slice(2));

if (args.command === 'build') {
  generate({
    contentDir: args.contentDir,
    outputDir: args.outputDir
  }).catch(error => {
    console.error('Error:', error.message);
    process.exit(1);
  });
} else {
  console.error('Unknown command:', args.command);
  process.exit(1);
}

import { parseMarkdownWithYaml, parseMarkdown, type PageMetadata } from './parser';

describe('parseMarkdownWithYaml', () => {
  it('parses YAML frontmatter with title', () => {
    const content = `---
title: Hello World
---
# Content
This is a test.`;

    const result = parseMarkdownWithYaml(content);

    expect(result.metadata.title).toBe('Hello World');
    expect(result.content).toContain('<h1>Content</h1>');
  });

  it('parses YAML frontmatter with date', () => {
    const content = `---
title: My Post
date: 2024-01-15
---
# Post Content`;

    const result = parseMarkdownWithYaml(content);

    expect(result.metadata.title).toBe('My Post');
    expect(result.metadata.date).toBe('2024-01-15');
  });

  it('parses YAML frontmatter with tags', () => {
    const content = `---
title: Tagged Post
tags: typescript, testing, ssg
---
# Content`;

    const result = parseMarkdownWithYaml(content);

    expect(result.metadata.tags).toEqual(['typescript', 'testing', 'ssg']);
  });

  it('parses YAML frontmatter with multiple fields', () => {
    const content = `---
title: Full Example
date: 2024-01-15
tags: test, example
author: John Doe
---
# Full Example

This is the content.`;

    const result = parseMarkdownWithYaml(content);

    expect(result.metadata.title).toBe('Full Example');
    expect(result.metadata.date).toBe('2024-01-15');
    expect(result.metadata.tags).toEqual(['test', 'example']);
    expect(result.metadata.author).toBe('John Doe');
    expect(result.content).toContain('<h1>Full Example</h1>');
    expect(result.content).toContain('This is the content');
  });

  it('handles markdown without frontmatter', () => {
    const content = `# No Frontmatter

This is just markdown.`;

    const result = parseMarkdownWithYaml(content);

    expect(result.metadata.title).toBeUndefined();
    expect(result.content).toContain('<h1>No Frontmatter</h1>');
    expect(result.content).toContain('This is just markdown');
  });

  it('handles empty tags field', () => {
    const content = `---
title: No Tags
tags:
---
Content`;

    const result = parseMarkdownWithYaml(content);

    expect(result.metadata.tags).toBeUndefined();
  });

  it('preserves markdown formatting', () => {
    const content = `---
title: Formatted
---
**bold** and *italic* and [link](http://example.com)`;

    const result = parseMarkdownWithYaml(content);

    expect(result.content).toContain('<strong>bold</strong>');
    expect(result.content).toContain('<em>italic</em>');
    expect(result.content).toContain('href="http://example.com"');
  });

  it('handles code blocks', () => {
    const content = `---
title: Code
---
\`\`\`typescript
const x = 42;
\`\`\``;

    const result = parseMarkdownWithYaml(content);

    expect(result.content).toContain('<code>');
    expect(result.content).toContain('const x = 42');
  });

  it('strips whitespace from tag values', () => {
    const content = `---
title: Test
tags: tag1 , tag2 , tag3
---
Content`;

    const result = parseMarkdownWithYaml(content);

    expect(result.metadata.tags).toEqual(['tag1', 'tag2', 'tag3']);
  });
});

describe('parseMarkdown', () => {
  it('parses JSON frontmatter via gray-matter', () => {
    const content = `---
title: "JSON Test"
tags: ["a", "b"]
---
# Content`;

    const result = parseMarkdown(content);

    expect(result.metadata.title).toBe('JSON Test');
    expect(Array.isArray(result.metadata.tags)).toBe(true);
  });

  it('handles markdown without any frontmatter', () => {
    const content = `# No Frontmatter
Just content.`;

    const result = parseMarkdown(content);

    expect(result.metadata).toEqual({});
    expect(result.content).toContain('<h1>No Frontmatter</h1>');
  });
});

import fs from 'fs';
import path from 'path';
import os from 'os';
import { generate } from './generator';

describe('generator', () => {
  let tempDir: string;
  let contentDir: string;
  let outputDir: string;

  beforeEach(() => {
    tempDir = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-test-'));
    contentDir = path.join(tempDir, 'content');
    outputDir = path.join(tempDir, 'dist');

    fs.mkdirSync(contentDir, { recursive: true });
  });

  afterEach(() => {
    fs.rmSync(tempDir, { recursive: true, force: true });
  });

  it('generates HTML files from markdown', async () => {
    const content = `---
title: Test Page
---
# Hello

This is a test page.`;

    fs.writeFileSync(path.join(contentDir, 'test.md'), content);

    await generate({ contentDir, outputDir });

    const outputFile = path.join(outputDir, 'test.html');
    expect(fs.existsSync(outputFile)).toBe(true);

    const html = fs.readFileSync(outputFile, 'utf-8');
    expect(html).toContain('<title>Test Page</title>');
    expect(html).toContain('<h1>Hello</h1>');
    expect(html).toContain('This is a test page');
  });

  it('generates index.html with all pages', async () => {
    fs.writeFileSync(
      path.join(contentDir, 'page1.md'),
      `---
title: Page One
date: 2024-01-15
---
Content 1`
    );
    fs.writeFileSync(
      path.join(contentDir, 'page2.md'),
      `---
title: Page Two
date: 2024-01-10
---
Content 2`
    );

    await generate({ contentDir, outputDir });

    const indexFile = path.join(outputDir, 'index.html');
    expect(fs.existsSync(indexFile)).toBe(true);

    const html = fs.readFileSync(indexFile, 'utf-8');
    expect(html).toContain('Page One');
    expect(html).toContain('Page Two');
    expect(html).toContain('href="page1.html"');
    expect(html).toContain('href="page2.html"');
  });

  it('sorts pages by date descending in index', async () => {
    fs.writeFileSync(
      path.join(contentDir, 'old.md'),
      `---
title: Old Post
date: 2024-01-01
---
Old`
    );
    fs.writeFileSync(
      path.join(contentDir, 'new.md'),
      `---
title: New Post
date: 2024-01-31
---
New`
    );

    await generate({ contentDir, outputDir });

    const html = fs.readFileSync(path.join(outputDir, 'index.html'), 'utf-8');
    const newPos = html.indexOf('New Post');
    const oldPos = html.indexOf('Old Post');
    expect(newPos).toBeLessThan(oldPos);
  });

  it('includes tags in generated pages', async () => {
    const content = `---
title: Tagged Page
tags: typescript, testing
---
Content`;

    fs.writeFileSync(path.join(contentDir, 'tagged.md'), content);

    await generate({ contentDir, outputDir });

    const html = fs.readFileSync(path.join(outputDir, 'tagged.html'), 'utf-8');
    expect(html).toContain('typescript');
    expect(html).toContain('testing');
    expect(html).toContain('class="tag"');
  });

  it('includes date in generated pages', async () => {
    const content = `---
title: Dated Page
date: 2024-01-15
---
Content`;

    fs.writeFileSync(path.join(contentDir, 'dated.md'), content);

    await generate({ contentDir, outputDir });

    const html = fs.readFileSync(path.join(outputDir, 'dated.html'), 'utf-8');
    expect(html).toContain('2024-01-15');
    expect(html).toContain('class="date"');
  });

  it('escapes HTML in titles', async () => {
    const content = `---
title: <script>alert('xss')</script>
---
Content`;

    fs.writeFileSync(path.join(contentDir, 'xss.md'), content);

    await generate({ contentDir, outputDir });

    const html = fs.readFileSync(path.join(outputDir, 'xss.html'), 'utf-8');
    expect(html).toContain('&lt;script&gt;');
    expect(html).not.toContain('<script>alert');
  });

  it('creates output directory if it does not exist', async () => {
    const nonExistentOutput = path.join(tempDir, 'new', 'dist');
    expect(fs.existsSync(nonExistentOutput)).toBe(false);

    fs.writeFileSync(path.join(contentDir, 'test.md'), `---
title: Test
---
Content`);

    await generate({ contentDir, outputDir: nonExistentOutput });

    expect(fs.existsSync(nonExistentOutput)).toBe(true);
    expect(fs.existsSync(path.join(nonExistentOutput, 'test.html'))).toBe(true);
  });

  it('throws error if content directory does not exist', async () => {
    const nonExistent = path.join(tempDir, 'nonexistent');

    await expect(
